python - <<'PY'
from semver import VersionInfo

for version, expected in [
    (VersionInfo(1, 2, 3, 'rc.1', 'build.2'), (1, 2, 3, 'rc.1', 'build.2')),
    (VersionInfo(1), (1, 0, 0, None, None)),
]:
    assert version.to_tuple() == expected
    assert isinstance(version.to_tuple(), tuple)
    assert isinstance(version.to_dict(), dict)
    assert version.to_dict() == dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), expected))
    for index in range(-5, 5):
        assert version[index] == expected[index]
    for start in (None, -8, -2, 0, 2, 8):
        for stop in (None, -8, -2, 0, 2, 8):
            for step in (None, -2, -1, 1, 2):
                index = slice(start, stop, step)
                assert version[index] == expected[index]
    for index in (-6, 5):
        try:
            version[index]
        except IndexError:
            pass
        else:
            raise AssertionError('Expected IndexError')
    for index in ('major', 1.5, None):
        try:
            version[index]
        except TypeError:
            pass
        else:
            raise AssertionError('Expected TypeError')
    parts = version.to_dict()
    parts['major'] = 99
    assert version.major == 1
print('Accessor and sequence checks passed')
PY
